#
# `which sh` for path
# on linux: /bin/sh
# on freebsd: /usr/local/bin/sh
#

function makefile_main()
{
echo "#
# Code generated by configure
# 
# Warning! All changes made in this file will be lost!
#

default:
	@echo '-+- >> Available targets:'
	@echo '-+- = dynamic (prefered for most systems)'
	@echo '-+- = static'
	@echo '-+- = debug'

dynamic:
	@make -f Makefile.key
	@echo '-+- Making dynamic'
	@make -f Makefile.dynamic

static:
	@make -f Makefile.key
	@echo '-+- Making static'
	@make -f Makefile.static

debug:
	@make -f Makefile.key
	@echo '-+- Making debug'
	@make -f Makefile.debug

release:
	@make -f Makefile.key
	@echo '-+- Making release'
	@make -f Makefile.release

src:
	@echo '-+- Making src'
	@make -f Makefile.src
	
clean:
	@echo '-+- Making clean'
	@make -f Makefile.clean
" > Makefile
}

function makefile_key()
{
echo "#
# Code generated by configure
# 
# Warning! All changes made in this file will be lost!
#

CC = gcc
OUT = key

$TARGET:
	@echo '-+- Making key'
	@echo '-+- Compiling key.c'
	@\$(CC) key.c -o \$(OUT)
	@echo '-+- Genereting key.h'
	@./key 
	@echo '-+- Please remove key.h when you finish compilation' " > Makefile.$TARGET
}

function makefile_up()
{
echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#

.SUFFIXES: .c .o

CC = gcc
OUT = $OUT
CFLAGS = $CFLAGS $FLAGS
LFLAGS = $LFLAGS

.c.o:
	@echo '-+- Compiling \$<'
	@\$(CC) -c \$< \$(CFLAGS)

EXE_DEPEND = md5.o \\
net.o \\
irc.o \\
cmds.o \\
ident.o \\
validate.o \\
functions.o \\
work.o \\
work_fast.o \\
main.o \\

$TARGET: \$(EXE_DEPEND)
	@echo '-+- Linking'
	@\$(CC) \$(EXE_DEPEND) -o \$(OUT) \$(CFLAGS) \$(LFLAGS) "  > Makefile.$TARGET
}

function makefile_done()
{

echo "	@echo '-+- Done'" >> Makefile.$TARGET
}

function makefile_release()
{
echo "	@echo '-+- Creating release'
	@mkdir cloner
	@mkdir cloner/vhost-examples	
	@echo -+- Striping debug information
	@strip \$(OUT)
	@echo '-+- Building validator'
	@\$(CC) md5.o -m32 -o validator validator.c 
	@echo '-+- Patching file'
	@./validator \$(OUT)
	@cp \$(OUT) cloner/\$(OUT)
	@ln -s \$(OUT) cloner/cloner
	@cp ../README  cloner/README
	@cp ../CHANGELOG cloner/CHANGELOG
	@cp ../vhost-examples/* cloner/vhost-examples	
	@tar -cf \$(OUT).tar cloner
	@rm -fr cloner
	@rm -fr \$(OUT)
	@gzip -9 -f \$(OUT).tar
	@mv \$(OUT).tar.gz ../\$(OUT).tar.gz" >> Makefile.$TARGET
}

function makefile_world()
{
echo "	@echo -+- Striping debug information
	@strip \$(OUT)
	@echo '-+- Building validator'
	@\$(CC) md5.o -m32 -o validator validator.c 
	@echo '-+- Patching file'
	@./validator \$(OUT)
	@mv \$(OUT) ../\$(OUT)
	@rm -fr ../cloner
	@ln -s \$(OUT) ../cloner" >> Makefile.$TARGET
}

function makefile_deb()
{
echo "#	@echo '-+- Building validator'
#	@\$(CC) md5.o -m32 -o validator validator.c 
#	@echo '-+- Patching file'
#	@./validator \$(OUT)
	@mv \$(OUT) ../\$(OUT)
	@rm -fr ../cloner 
	@ln -s \$(OUT) ../cloner" >> Makefile.$TARGET
}


function makefile_src()
{
    echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#    

OUT = cloner-$VER-src

$TARGET:
	@echo '-+- Cleaning up'
	@rm -fr cloner
	@rm -fr *.o Makefile Makefile.* key.h key
	@echo '-+- Creating struct of files'
	@mkdir cloner
	@mkdir cloner/vhost-examples	
	@mkdir cloner/src
	@mkdir cloner/jococloner
	@cp ../vhost-examples/* cloner/vhost-examples/
	@cp configure cloner/src/configure
	@cp configure.sh cloner/src/configure.sh
	@cp *.h cloner/src/
	@cp *.c cloner/src/
	@cp ../jococloner/* cloner/jococloner/
	@cp ../CHANGELOG cloner/CHANGELOG
	@cp ../README cloner/README
	@echo '-+- Creating archive'
	@tar -cf \$(OUT).tar cloner/
	@rm -fr cloner
	@rm -fr \$(OUT)
	@gzip -9 -f \$(OUT).tar
	@mv \$(OUT).tar.gz ../\$(OUT).tar.gz" > Makefile.$TARGET    
}

function makefile_clean()
{
    echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#    

OUT = $OUT

$TARGET:
	@echo '-+- Cleaning up'
	@rm -fr cloner *.o validator key.h key Makefile Makefile.* *.log ../cloner ../\$(OUT)
	@rm -fr ../*.log " > Makefile.$TARGET		
    
}

function help()
{
	echo "-+-  --with-ipv6 - configure with ipv6 enabled"
	echo "-+-  --without-ipv6 - configure without ipv6 (default on)"	
	echo "-+-  --without-validator - turn off binary validation on start (default off)"
	echo "-+-  --help - this help ;-P" 
    exit 1
}

function getarg()
{
    IPSET=false
    VALIDSET=false
    
    VALIDATOR=false
    HAVE_IPV6=false
    
    if [ "$ARG2" = "" ]; then
        if [ "$ARG" = "" ]; then
	        if [ "$UNAME" = "cygwin" ]; then
		        HAVE_IPV6=false
	        else
		        HAVE_IPV6=true
	        fi
	        VALIDATOR=true
	    
	        # check if that wasnt reset
	        IPSET=true
	        VALIDSET=true
	    else 
	        if [ "$ARG" = "--with-ipv6" ]; then
		        HAVE_IPV6=true
		        IPSET=true
	        elif [ "$ARG" = "--without-ipv6" ]; then
		        HAVE_IPV6=false
		        IPSET=true
	        elif [ "$ARG" = "--without-validator" ]; then
		        VALIDATOR=false
		        VALIDSET=true
	        else
		        help  
	    fi

	fi
    else
	    if [ "$ARG2" = "--with-ipv6" ]; then
	        if [ $IPSET = true ]; then
		        echo "-+- Duplicated $ARG2 flag"
		        exit 1
	        else
		        HAVE_IPV6=true
		        IPSET=true
	        fi
	    elif [ "$ARG2" = "--without-ipv6" ]; then
	        if [ $IPSET = true ]; then
		        echo "-+- Duplicated $ARG2 flag"
		        exit 1
	        else
		        HAVE_IPV6=false
		        IPSET=true
	        fi
	    elif [ "$ARG2" = "--without-validator" ]; then
	        if [ $VALIDSET = true ]; then
		        echo "-+- Duplicated $ARG2 flag"
		        exit 1
	        else
		        VALIDATOR=false
		        VALIDSET=true
	        fi
	    else
	        help    
	    fi
    fi
}

function make_echo()
{
    echo "-+- Generating Makefile.$TARGET"    
}

function make_me()
{
    makefile_up
    makefile_world
}


function do_dynamic()
{
    make_echo
    FLAGS=""
    make_me
}

function do_static()
{
    make_echo
    FLAGS="-static"
    make_me
}

function do_debug()
{
    make_echo
    FLAGS="-DDEBUG"
    CFLAGS="-Wall -m32 -ggdb"
    makefile_up
    makefile_deb
}

function do_release()
{
    FLAGS="-static"
    if [ $HAVE_IPV6 = true ]; then
	CFLAGS="-pipe -O2 -DHAVE_IPV6 -DHAVE_VALIDATOR -m32"
    else
	CFLAGS="-pipe -O2 -DHAVE_VALIDATOR -m32"
    fi
    makefile_up
    makefile_release
}

UNAME=`uname | awk '{ print tolower($1) }'`

# fix names
case $UNAME in
    SunOS) UNAME="sunos";;
    cygwin_*) UNAME="cygwin";;
esac

MACHINE=`uname -m`

VER=`cat defines.h | egrep CLONER_VERSION_STR | awk '{ print substr($3, 2, length($3)-2) }'`
VER=`echo -e $VER`
OUT="cloner-$VER-$UNAME"
GCC=`gcc -v 2>&1 | tail -1 | awk '{print $3}'`

ARG="$1"
ARG2="$2"

if [ "$UNAME" = "sunos" ]; then 
    $LFLAGS="-lsocket -lnsl"
    $CFLAGS="-DSUNOS -pipe -O2 -m32"    
elif [ "$UNAME" = "cygwin" ]; then 
    LFLAGS=""
    CFLAGS="-DWINDOWS -pipe -O2 -m32"
else
    LFLAGS=""
    CFLAGS="-pipe -O2 -m32"
    
#    GCCVER=`echo $GCC | sed 's/[.]*//g'`
#
#   if [ $GCCVER -ge 423 ]; then
#        CFLAGS="-march=native -pipe -O2"
#    else
#	    CFLAGS="-march=$MACHINE -pipe -O2"
#    fi
fi

getarg

echo "-+- Running configure"
echo "-+- Operating system: $UNAME"
echo "-+- Architecture type: $MACHINE"
echo "-+- Build for: i386 and newer"
echo "-+- Gnu C Compiler version: $GCC"
echo -n "-+- IPv6 enabled: "
if [ $HAVE_IPV6 = true ]; then
    echo "yes (./configure --without-ipv6 to turn off)"
    CFLAGS="$CFLAGS -DHAVE_IPV6"
else
    echo "no (./configure --with-ipv6 to trun it on)"
fi
echo -n "-+- Validator enabled: "
if [ $VALIDATOR = true ]; then
    echo "yes (./configure --without-validator to turn off)"
    CFLAGS="$CFLAGS -DHAVE_VALIDATOR"    
else
    echo "no (binary will be unprotected now)"            
fi
echo "-+- Generating Makefile"
makefile_main
for i in "key" "dynamic" "static" "debug" "release" "src" "clean"
do
    TARGET="$i"    
    case $TARGET in
	"key") makefile_key ;;
	"dynamic") do_dynamic ;;
	"static") do_static ;;
	"debug") do_debug ;;
	"release") do_release ;;
	"src") makefile_src ;;
	"clean") makefile_clean ;;
    esac 
    makefile_done
done
echo '-+- Configure is done'

